// Valid documents of every type (docs/firestore-model.md) and the test environment. The documents
// come from shared/fixtures/firestore_documents.json (the test data shared with the web's Dart
// tests; generated by scripts/export_fixtures.mjs from fixtureData.js), so both sides test the
// same documents.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { initializeTestEnvironment } from '@firebase/rules-unit-testing';
import { Bytes, serverTimestamp } from 'firebase/firestore';

export const PROJECT_ID = 'tiominuter-e43f7';
const RULES = fileURLToPath(new URL('../../firestore.rules', import.meta.url));
const SHARED = JSON.parse(
  readFileSync(fileURLToPath(new URL('../../../shared/fixtures/firestore_documents.json', import.meta.url)), 'utf8'),
);

/** Uses the emulator started by `firebase emulators:exec` (FIRESTORE_EMULATOR_HOST). */
export async function createEnvironment() {
  return initializeTestEnvironment({
    projectId: PROJECT_ID,
    firestore: { rules: readFileSync(RULES, 'utf8') },
  });
}

/**
 * A fresh copy of a shared document: {"$serverTimestamp": true} → serverTimestamp(),
 * {"$arg": name} → args[name].
 */
function shared(name, args = {}) {
  const resolve = (value) => {
    if (Array.isArray(value)) return value.map(resolve);
    if (value && typeof value === 'object') {
      if (value.$serverTimestamp === true) return serverTimestamp();
      if (typeof value.$arg === 'string') {
        if (!(value.$arg in args)) throw new Error(`fixture ${name} needs the argument ${value.$arg}`);
        return args[value.$arg];
      }
      return Object.fromEntries(Object.entries(value).map(([key, inner]) => [key, resolve(inner)]));
    }
    return value;
  };
  return resolve(SHARED.documents[name]);
}

export const { ENTRY_ID, PROGRAM_ID, WEEK, WORKOUT_ID } = SHARED.constants;

export function user(overrides = {}) {
  return { ...shared('user'), ...overrides };
}

export function gymEntry(overrides = {}) {
  return { ...shared('gymEntry'), ...overrides };
}

export function activityEntry(overrides = {}) {
  return { ...shared('activityEntry'), ...overrides };
}

export function weeklyGoal(overrides = {}) {
  return { ...shared('weeklyGoal'), ...overrides };
}

export function program(overrides = {}) {
  return { ...shared('program'), ...overrides };
}

export function programWorkout(overrides = {}) {
  return { ...shared('programWorkout'), ...overrides };
}

export function dailyProgress(overrides = {}) {
  return { ...shared('dailyProgress'), ...overrides };
}

export function programCompletion(overrides = {}) {
  return { ...shared('programCompletion'), ...overrides };
}

/** A deletion: only the id field, deleted, updatedAt and schemaVersion. */
export function tombstone(idField, id) {
  return { [idField]: id, ...shared('tombstone') };
}

/** Every document type: its path under users/{uid}, a valid doc and its tombstone (if any). */
export function documentTypes(uid) {
  const programPath = `users/${uid}/programs/${PROGRAM_ID}`;
  return [
    { name: 'user', path: `users/${uid}`, valid: user, update: { displayName: 'Alex R.' } },
    {
      name: 'training entry (gym)',
      path: `users/${uid}/trainingLog/${ENTRY_ID}`,
      valid: gymEntry,
      update: { title: 'Pull Day (edited)' },
      tombstone: () => tombstone('entryId', ENTRY_ID),
    },
    {
      name: 'training entry (activity)',
      path: `users/${uid}/trainingLog/${ENTRY_ID}`,
      valid: activityEntry,
      update: { intensity: 'HARD' },
      tombstone: () => tombstone('entryId', ENTRY_ID),
    },
    {
      name: 'weekly goal',
      path: `users/${uid}/weeklyGoals/${WEEK}`,
      valid: weeklyGoal,
      update: { workoutsPerWeek: 5 },
      tombstone: () => tombstone('effectiveFromWeek', WEEK),
    },
    {
      name: 'program',
      path: programPath,
      valid: program,
      update: { focus: 'CORE' },
      tombstone: () => tombstone('programId', PROGRAM_ID),
    },
    {
      name: 'program workout',
      path: `${programPath}/workouts/${WORKOUT_ID}`,
      valid: programWorkout,
      update: { isDeload: true },
      tombstone: () => tombstone('workoutId', WORKOUT_ID),
    },
    {
      name: 'program completion',
      path: `${programPath}/completions/${WORKOUT_ID}`,
      valid: programCompletion,
      update: { completedAt: 1761076800000 },
      tombstone: () => tombstone('workoutId', WORKOUT_ID),
    },
    // Never tombstoned (no tombstone builder)
    {
      name: 'daily progress',
      path: `users/${uid}/dailyProgress/state`,
      valid: dailyProgress,
      update: { lastCompletedDay: 8 },
    },
  ];
}

// ---------- Groups ----------

export const { GROUP_ID, OTHER_GROUP_ID, INVITE_CODE, NEW_INVITE_CODE } = SHARED.constants;

/** A group id for test number [n] (20 alphanumeric characters, like a Firestore auto id). */
export function groupId(n) {
  return `grp${String(n).padStart(17, '0')}`;
}

/** An invite code for test number [n] (unambiguous alphabet: no 0 O 1 I L). */
export function inviteCode(n) {
  const alphabet = '23456789ABCDEFGHJKMNPQRSTUVWXYZ';
  let code = '';
  let rest = n;
  for (let i = 0; i < 8; i++) {
    code = alphabet[rest % alphabet.length] + code;
    rest = Math.floor(rest / alphabet.length);
  }
  return code;
}

export function group(ownerUid, overrides = {}) {
  return { ...shared('group', { ownerUid }), ...overrides };
}

/** A member's public summary: name, photo, the weekly numbers and the sources of each day. */
export function member(overrides = {}) {
  return { ...shared('member'), ...overrides };
}

export function invite(groupIdValue, overrides = {}) {
  return { ...shared('invite', { groupId: groupIdValue }), ...overrides };
}

export function membership(groupIdValue) {
  return shared('membership', { groupId: groupIdValue });
}

// ---------- Feed ----------

export const { POST_ID } = SHARED.constants;

/** A JPEG-sized thumbnail of [size] bytes (the rules only check type and size). */
export function thumbBytes(size) {
  return Bytes.fromUint8Array(new Uint8Array(size).fill(0xff));
}

/** One counted workout as the group sees it (Wednesday of WEEK). */
export function post(authorUid, overrides = {}) {
  return { ...shared('post', { authorUid }), ...overrides };
}
